package leobog

// The Hi75's keys, as the LEOBOG ONE driver lays them out (Dev\kb\2\KB.ini):
// the matrix index the firmware uses for colors and remaps, and the key's
// rectangle on a LayoutW × LayoutH drawing.

// Key is one key of the keyboard.
type Key struct {
	Index int    `json:"index"`
	Name  string `json:"name"`
	X     int    `json:"x"`
	Y     int    `json:"y"`
	W     int    `json:"w"`
	H     int    `json:"h"`
}

// The drawing's size.
const (
	LayoutW = 679
	LayoutH = 284
)

// FnIndex is the Fn key, which switches to the Fn layer and cannot be remapped.
const FnIndex = 59

